CREATE OR REPLACE PROCEDURE eks_calculation.srmara_eks_item_constructbafromea_ins()
BEGIN
INSERT INTO idq_production_eks_calculation.stmara_eks_item_1 (itemid, bitflag, employeeid, cr_locationid, itemgrouptypeid, itemno, shortdesc_int, shortdesc_nat, description_int, description_nat, in_use, zlegacymandt, zlegacymatnr, zlegacymatkl, zlegacymeins, zlegacysatnr, zlegacypmata, zactive, zernam, zaenam, zmtart, zmatkl, zbismt, zmeins, zzeinr, zntgew, ztragr, zspart, zbwscl, zvabme, zbegru, zattyp, zmstae, zmstde, ztaklv, zinhme, zinhal, zvpreh, zbflme, zisvalidbitflag, zisin_use, zisfood, ziscurrentcontract, znegotiatingcountry, zarticletype, zitem_ba, zsource, constructed, constructedfrom, targetsystem, targetclient)
(SELECT CAST(ROUND(CAST(itemid AS BIGNUMERIC),0) AS INT64), bitflag, employeeid, cr_locationid, itemgrouptypeid, CAST(itemno AS INT64), shortdesc_int, shortdesc_nat, description_int, description_nat, in_use, zlegacymandt, zlegacymatnr, zlegacymatkl, zlegacymeins, SUBSTR(CAST(zlegacysatnr AS STRING), 1, 50) AS zlegacysatnr, SUBSTR(CAST(zlegacypmata AS STRING), 1, 50) AS zlegacypmata, zactive, zernam, zaenam, zmtart, zmatkl, zbismt, zmeins, zzeinr, CAST(zntgew AS INT64), ztragr, zspart, zbwscl, zvabme, zbegru, zattyp, zmstae, zmstde, ztaklv, SUBSTR(CAST(zinhme AS STRING), 1, 3) AS zinhme, zinhal, CAST(zvpreh AS INTEGER) AS zvpreh, zbflme, zisvalidbitflag, zisin_use, zisfood, ziscurrentcontract, znegotiatingcountry, zarticletype, CAST(zitem_ba AS INTEGER), zsource, constructed, SUBSTR(CAST(constructedfrom AS STRING), 1, 255) AS constructedfrom, targetsystem, targetclient
    FROM idq_production_eks_calculation.srmara_eks_item_constructbafromea_inssel_1);
END;

